/// Per-map events; the instance name is the handle. On listen the native side sends the current
/// state (floors, selected floor, camera mode, style source, error, guidance; the journey state),
/// so a late listener misses nothing that is still true.
Stream<MapMsgEvent> mapEvents({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel mapEventsChannel = EventChannel(
    'dev.flutter.pigeon.flutter_proximiio_map.MapEventApi.mapEvents$instanceName',
    pigeonMethodCodec,
  );
  return mapEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as MapMsgEvent;
  });
}

Stream<MapMsgJourneyEvent> journeyEvents({String instanceName = ''}) {
